CREATE OR REPLACE FUNCTION public.can_access_student_department(_user_id uuid, _department_id uuid, _student_user_id uuid DEFAULT NULL, _write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_user_id, 'admin'::public.app_role) OR (NOT _write AND _student_user_id = _user_id) OR (_department_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.staff_department_scope s WHERE s.user_id = _user_id AND s.department_id = _department_id AND (NOT _write OR s.access_level = 'full'))) OR (_department_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.staff_profiles s WHERE s.user_id = _user_id AND s.department_id = _department_id AND (NOT _write OR NOT EXISTS (SELECT 1 FROM public.staff_department_scope scope WHERE scope.user_id = _user_id AND scope.department_id = _department_id AND scope.access_level <> 'full')))) $$;
GRANT EXECUTE ON FUNCTION public.can_access_student_department(uuid, uuid, uuid, boolean) TO authenticated, service_role;
CREATE POLICY student_department_read_boundary ON public.student_profiles AS RESTRICTIVE FOR SELECT TO authenticated USING (public.can_access_student_department(auth.uid(), department_id, user_id, false));
CREATE POLICY student_department_update_boundary ON public.student_profiles AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.can_access_student_department(auth.uid(), department_id, user_id, true)) WITH CHECK (public.can_access_student_department(auth.uid(), department_id, user_id, true));
CREATE POLICY student_department_insert_boundary ON public.student_profiles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (public.can_access_student_department(auth.uid(), department_id, user_id, true));